from odoo import fields, models

# Letterhead modes, shared by letter.template / letter.document / res.company.
# `banner` and `classic` are generated by QWeb; `image`, `pdf_overlay` and
# `plain` use (or leave room for) the company's own letterhead.
LETTERHEAD_MODES = [
    ("banner", "Dark banner (generated)"),
    ("classic", "Understated classic (generated)"),
    ("image", "Uploaded image (PNG/JPG)"),
    ("pdf_overlay", "Uploaded PDF (overlay)"),
    ("plain", "No letterhead (pre-printed paper)"),
]

# Curated mail-merge token palette. Surfaced as a static legend in the
# template form view; rendering itself accepts any valid expression.
LETTER_MERGE_TOKENS = [
    ("{{ object.partner_id.name }}", "Recipient name"),
    ("{{ object.partner_id.parent_id.name }}", "Recipient organization"),
    ("{{ object.recipient_name }}", "Recipient name (frozen on the letter)"),
    ("{{ object.letter_date }}", "Letter date"),
    ("{{ object.reference }}", "Letter reference (LET-YYYY-NNN)"),
    ("{{ object.company_id.name }}", "Sender name"),
    ("{{ object.signatory_id.name }}", "Signatory name"),
    ("{{ object.signatory_function }}", "Signatory title"),
]


class LetterTemplate(models.Model):
    _name = "letter.template"
    _description = "Letter template"
    _order = "name"

    name = fields.Char(string="Name", required=True)
    active = fields.Boolean(default=True)
    subject = fields.Char(
        string="Subject",
        help="Default letter title. Can contain merge fields.",
    )
    body_html = fields.Html(
        string="Body",
        # Nettoyé comme un modèle de courriel d'Odoo : les balises QWeb (<t t-out>)
        # et les styles restent, le script et les « on… » partent.
        sanitize="email_outgoing",
        help="Template body. Merge fields: {{ object.field }} or QWeb <t "
             "t-out=\"object.field\"/>.",
    )
    letterhead_style = fields.Selection(
        LETTERHEAD_MODES,
        string="Letterhead",
        default="banner",
        required=True,
    )
    note = fields.Text(string="Internal description")
    quicktext_ids = fields.Many2many(
        "letter.quicktext",
        string="Suggested text blocks",
    )
